import Card from "@mui/material/Card";
import CardActions from "@mui/material/CardActions";
import CardContent from "@mui/material/CardContent";
import Button from "@mui/material/Button";
import Typography from "@mui/material/Typography";
import Grid from "@mui/material/Grid";
import IconButton from "@mui/material/IconButton";
import CheckIcon from "@mui/icons-material/Check";
import DeleteIcon from "@mui/icons-material/Delete";
import EditIcon from "@mui/icons-material/Edit";
export default function Todo() {
  return (
    <>
      <Card
        sx={{
          minWidth: 275,
          background: "#283593",
          color: "white",
          marginTop: 8,
        }}
      >
        <CardContent>
          <Grid container spacing={1}>
            <Grid xs={8}>
              <Typography variant="h5" sx={{ textAlign: "right" }}>
                المهمة الاولى
              </Typography>
            </Grid>

            <Grid
              display="flex"
              justifyContent="space-around"
              alignItems="center"
              xs={4}
            >
              <IconButton
                sx={{
                  color: "#8bc344a",
                  backgroundColor: "#8bc344a",
                  border: "3px solid #8bc344a",
                  transition: "all 0.3s",
                  "&:hover": {
                    backgroundColor: "#6fa22f", // slightly darker on hover
                  },
                }}
              >
                <CheckIcon />
              </IconButton>

              <IconButton
                sx={{
                  color: "#1769aa",
                  backgroundColor: "#1769aa",
                  border: "3px solid #1769aa",
                  transition: "all 0.3s",
                  "&:hover": {
                    backgroundColor: "#124d88", // slightly darker on hover
                  },
                }}
              >
                <EditIcon />
              </IconButton>

              <IconButton
                sx={{
                  color: "#b23c17",
                  backgroundColor: "#b23c17",
                  border: "3px solid #b23c17",
                  transition: "all 0.3s",
                  "&:hover": {
                    backgroundColor: "#872c11", // slightly darker on hover
                  },
                }}
              >
                <DeleteIcon />
              </IconButton>
            </Grid>
          </Grid>
        </CardContent>
      </Card>
    </>
  );
}
